// CORRECT
DB::transaction(function () use ($invoice, $payment) {
    Log::info('Payment processing started', [
        'invoice_id'      => $invoice->id,
        'amount'          => $payment->amount,
        'balance_before'  => $invoice->balance,
    ]);

    $invoice->applyPayment($payment);
    $ledgerEntry = LedgerEntry::create([...]);

    Log::info('Payment committed', [
        'invoice_id'     => $invoice->id,
        'balance_after'  => $invoice->fresh()->balance,
        'ledger_entry'   => $ledgerEntry->id,
    ]);
});

// Consistent rounding
$amount = round($rawAmount, 2, PHP_ROUND_HALF_UP);

// Or with bcmath
$amount = bcadd($subtotal, $tax, 2);

try {
    DB::transaction(function () use ($data) {
        // financial logic
    });
} catch (\Throwable $e) {
    Log::error('Financial operation failed', [
        'operation'  => 'payment_processing',
        'amount'     => $data['amount'] ?? null,
        'currency'   => $data['currency'] ?? null,
        'account_id' => $data['account_id'] ?? null,
        'user_id'    => auth()->id(),
        'error'      => $e->getMessage(),
        'file'       => $e->getFile(),
        'line'       => $e->getLine(),
    ]);
    throw $e; // re-throw after logging
}
